/**
 * @return {string}
 */
Date.prototype.nextDay = function() {
    // Add exactly one day in milliseconds (UTC has no DST shifts)
    const next = new Date(this.getTime() + 24 * 60 * 60 * 1000);
    // toISOString() is "YYYY-MM-DDTHH:mm:ss.sssZ": keep the date part
    return next.toISOString().slice(0, 10);
};

/**
 * const date = new Date("2014-06-20");
 * date.nextDay(); // "2014-06-21"
 */
